// === Tab: sketch149304 ===
// let Field
// let trails via let noise. 
// let mouse to change particle motion. 
// let to randomize parameters.
// let with Processing.js (processingjs.org)
// by function Turner(airtightinteractive.com)

let numParticles;
let fadeAmount;
let maxLen = 120;
let strokeAmount;

let particles = new Array(numParticles);
let FIELDWIDTH = 3840;
let FIELDHEIGHT = 2160;

function setup() {
    createCanvas(3840, 2160);
    colorMode(HSB, 100);
    background(0);  
    randomize()
}

function randomize(){

    numParticles = random(150,520);
    fadeAmount = random(.5,20);
    maxLen = random(30,200);
    strokeAmount = random(0.02,0.3);

    for(i=0; i<numParticles; i++){
        particles[i]=new Particle(i/5000.0);
    }
}

function mouseClicked() {
    randomize();
}

function draw() {

    noStroke();
    fill(0,fadeAmount);
    rect(0,0,width,height);//fade background
    translate(-150,-25);
    translate((width- FIELDWIDTH)/2,(height- FIELDHEIGHT)/2);
    for(i=0; i<numParticles; i++){
        particles[i].update();//render particles
    } 

}

class Particle {
  id,x,y,xp,yp,s,d,sColor,len,z,zp;

  constructor(_id) {
    id=_id;
    init();
  }

    function init(){
        x=xp=random(0,FIELDWIDTH);
        y=yp=random(0,FIELDHEIGHT);
        z=zp=0;
        s=random(2,7);
        sColor = map(x,0,FIELDWIDTH,0,100);
        len = random(1,maxLen-1);
    }

    function update(){

        id+=0.01;

        if ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) == 0|| (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) == 0){
            window.simulatedMouseY = 1;
            window.simulatedMouseX = 1;         
        }

        d=(noise(id,x/(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),y/(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))-0.5)*(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));  

        x+=cos(radians(d))*s;
        y+=sin(radians(d))*s;

        strokeWeight((maxLen - len)*strokeAmount);
        stroke(sColor,80,90);
        line(xp,yp,x,y);
        xp=x;
        yp=y;
        len++;
        if (len >= maxLen) init();
    }

}

